extends Camera2D

@export var target_path: NodePath
@export var fixed_x: float = 640.0
@export var vertical_smoothing: float = 5.0

var _target: Node2D


func _ready() -> void:
	if not target_path.is_empty():
		_target = get_node_or_null(target_path)
	make_current()


func _physics_process(delta: float) -> void:
	if not is_instance_valid(_target):
		return
	var target_y := _target.global_position.y
	global_position.x = fixed_x
	global_position.y = lerpf(global_position.y, target_y, 1.0 - exp(-vertical_smoothing * delta))

shader_type canvas_item;

uniform float line_density : hint_range(100.0, 800.0) = 320.0;
uniform float line_strength : hint_range(0.0, 1.0) = 0.12;
uniform float chroma_strength : hint_range(0.0, 0.1) = 0.015;
uniform float noise_strength : hint_range(0.0, 0.2) = 0.03;
uniform float vignette_strength : hint_range(0.0, 1.0) = 0.25;

void fragment() {
	float scan = step(0.5, fract(SCREEN_UV.y * line_density));
	float scan_alpha = scan * line_strength;

	float noise = fract(sin(dot(SCREEN_UV, vec2(12.9898, 78.233)) + TIME * 0.3) * 43758.5453);
	float noise_val = (noise - 0.5) * noise_strength;

	vec2 center = SCREEN_UV - vec2(0.5);
	float vignette = 1.0 - dot(center, center) * vignette_strength * 4.0;

	float r = chroma_strength * sin(SCREEN_UV.y * 900.0 + TIME * 2.0);
	float b = chroma_strength * cos(SCREEN_UV.y * 900.0 + TIME * 2.0);

	vec3 col = vec3(r + noise_val, noise_val, b + noise_val);
	col *= vignette;

	COLOR = vec4(col, scan_alpha);
}

